#!/usr/bin/env bash
# Generated by: Claude Opus 5.5
# Generation date: 2026-10-11
# Last modified by: Claude Opus 5.5
# Last modified: 2026-10-12
#
# Send one prompt to Ministral and Gemma (same image version) and print both
# answers with timings. Starts either server via run-server.sh if needed. Each
# model is unloaded after its answer, so only one is in RAM at a time.
#
# Usage: compare.sh [-v VERSION] [-t] "prompt"
#   -t  allow thinking (reasoning) where the model supports it; off by default so
#       output tokens are comparable
# Env:   MINISTRAL_PORT (default 11434), GEMMA_PORT (default 11435), plus run-server.sh's
set -euo pipefail

script_dir=$(dirname "$(readlink -f "$0")")
# shellcheck source=scripts/common.sh
source "$script_dir/common.sh"

usage="usage: $(basename "$0") [-v VERSION] [-t] \"prompt\""
version=latest
think=false
while getopts 'v:t' opt; do
  case $opt in
    v) version=$OPTARG ;;
    t) think=true ;;
    *) die "$usage" ;;
  esac
done
shift $((OPTIND - 1))
[[ $# -eq 1 && -n "$1" ]] || die "$usage"
prompt=$1

require curl jq

# Resolve once, from Ministral's tags, so both run the same version
version=$(resolve_version ministral-3-3b "$version")

declare -A ports=([ministral-3-3b]=${MINISTRAL_PORT:-11434} [gemma4-e4b]=${GEMMA_PORT:-11435})
declare -A tags=([ministral-3-3b]=ministral-3:3b-instruct-2512-q4_K_M [gemma4-e4b]=gemma4:e4b-it-q4_K_M)

for model in ministral-3-3b gemma4-e4b; do
  # run-server.sh refuses to proceed if this model runs from another version
  "$script_dir/run-server.sh" "$model" "$version" "${ports[$model]}"
done

echo
echo "Image version: $version"
echo "Thinking: $([[ $think == true ]] && echo "allowed (-t)" || echo "off")"
echo "Prompt: $prompt"

# Without -t, send "think": false (accepted by every model). With -t, omit it:
# Ollama then enables thinking only for models that support it.
# keep_alive 0 unloads each model after its answer, so only one is in RAM at a time.
request() {
  jq -n --arg m "$1" --arg p "$2" --argjson think "$think" \
    '{model: $m, prompt: $p, stream: false, keep_alive: 0} + (if $think then {} else {think: false} end)'
}

# One-line timing summary. Ollama durations are in nanoseconds; eval_count
# includes thinking tokens, so their share is estimated from character counts.
# Variable names avoid jq keywords such as "end" (rejected by jq 1.6).
summary() {
  jq -r --arg t0 "$1" --arg t1 "$2" '
    def rate(n; d): if d > 0 then (n / (d / 1e9) * 10 | round / 10) else 0 end;
    def r1: . * 10 | round / 10;
    (($t1 | tonumber) - ($t0 | tonumber)) as $wall
    | ((.thinking // "") | length) as $tc
    | ((.response // "") | length) as $rc
    | (.eval_count // 0) as $n
    | (if $tc > 0 then ($n * $tc / ($tc + $rc) | round) else 0 end) as $think_tok
    | "load \((.load_duration // 0) / 1e9 | r1) s | "
      + "prompt \(.prompt_eval_count // 0) tok @ \(rate(.prompt_eval_count // 0; .prompt_eval_duration // 0)) tok/s | "
      + "output \($n) tok @ \(rate($n; .eval_duration // 0)) tok/s"
      + (if $think_tok > 0 then " (≈\($think_tok) thinking, ≈\($n - $think_tok) answer)" else "" end)
      + " | wall \($wall | r1) s"'
}

# Sequential, so the two models don't compete for the CPU
for model in ministral-3-3b gemma4-e4b; do
  start=$(date +%s.%N)
  reply=$(curl -fsS --max-time 1800 "http://127.0.0.1:${ports[$model]}/api/generate" \
    -d "$(request "${tags[$model]}" "$prompt")") \
    || die "request to $model failed"
  finish=$(date +%s.%N)

  echo
  echo "=== ${tags[$model]} (port ${ports[$model]})"
  if [[ -n "$(jq -r '.thinking // empty' <<<"$reply")" ]]; then
    echo "--- thinking"
    jq -r '.thinking' <<<"$reply"
    echo "--- answer"
  fi
  jq -r '.response' <<<"$reply"
  echo "---"
  summary "$start" "$finish" <<<"$reply"
done
